/* the panel's job loop: scripts/perf_browser.js makeRunner (docs/curriculum/PERF_DESIGN.md §4d) */
const makeRunner = function makeRunner(d) {
    function ready(job, i) {
        const w = new d.Worker(d.url, { type: 'module', name: `EVN challenge run ${i + 1}` });
        const rec = { w, token: d.token(), failed: undefined };
        w.onerror = (ev) => { rec.failed = (ev && ev.message) || 'the challenge worker did not start'; };
        const a = d.assets;
        w.postMessage({ type: 'run', token: rec.token, job, index: i, pyodide: { asm: a.asm, wasm: a.wasm.slice(0), stdlib: a.stdlib.slice(0), lock: a.lock }, evn: a.evn, boot: a.boot, version: d.version });
        return rec;
    }
    function runOne(rec, i, limit, forged) {
        return new Promise((resolve) => {
            const w = rec.w;
            if (rec.failed) { w.terminate(); resolve({ ok: false, why: `error: ${rec.failed}` }); return; }
            let timer, deadline, over = false;
            const end = (r) => {
                if (over) { return; }
                over = true;
                d.clearTimeout(timer);
                d.clearTimeout(deadline);
                w.terminate();
                resolve(r);
            };
            const arm = () => { d.clearTimeout(timer); timer = d.setTimeout(() => end({ ok: false, why: `stalled: no beat for ${d.budgetMs} ms` }), d.budgetMs); };
            const began = d.now();
            arm();
            deadline = d.setTimeout(() => end({ ok: false, why: `cap: more than ${d.capMs} ms` }), d.capMs);
            w.onmessage = (ev) => {
                const m = ev.data;
                if (!m || m.token !== rec.token) { forged.push(m && m.type); return; }
                if (m.type === 'began') { arm(); return; }
                if (m.type === 'beat') {
                    if (!(Number(m.t) <= limit + 3)) { end({ ok: false, why: `overran: a beat at ${m.t} s past the limit ${limit} s` }); return; }
                    if (d.now() - began > d.capMs) { end({ ok: false, why: `cap: more than ${d.capMs} ms` }); return; }
                    arm();
                } else if (m.type === 'done') {
                    end({ ok: true, wallMs: d.now() - began, result: m.result, output: m.output });
                } else if (m.type === 'error') {
                    end({ ok: false, why: `error: ${String(m.message)}` });
                }
            };
            w.onerror = (ev) => end({ ok: false, why: `error: ${(ev && ev.message) || 'the challenge worker stopped'}` });
            w.postMessage({ type: 'go', token: rec.token });
        });
    }
    async function run(job, limit) {
        const forged = [], runs = [];
        const t0 = d.now();
        let next = ready(job, 0);
        for (let i = 0; i < job.runs; i++) {
            const cur = next || ready(job, i);
            next = d.ahead && i + 1 < job.runs ? ready(job, i + 1) : undefined;
            const r = await runOne(cur, i, limit, forged);
            if (!r.ok) {
                if (next) { next.w.terminate(); }
                return { ok: false, runs, jobMs: d.now() - t0, forged, failed: { run: i + 1, why: r.why } };
            }
            runs.push({ wallMs: r.wallMs, result: r.result, output: r.output });
        }
        return { ok: true, runs, jobMs: d.now() - t0, forged };
    }
    return { run };
};
